// HasOauthApp applies the HasEdge predicate on the "oauthApp" edge.
func HasOauthApp() predicate.OAuthSelfHostedAuthorization {
	return predicate.OAuthSelfHostedAuthorization(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OauthAppTable, OauthAppColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOauthAppWith applies the HasEdge predicate on the "oauthApp" edge with a given conditions (other predicates).
func HasOauthAppWith(preds ...predicate.OAuthApp) predicate.OAuthSelfHostedAuthorization {
	return predicate.OAuthSelfHostedAuthorization(func(s *sql.Selector) {
		step := newOauthAppStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OAuthSelfHostedAuthorization) predicate.OAuthSelfHostedAuthorization {
	return predicate.OAuthSelfHostedAuthorization(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OAuthSelfHostedAuthorization) predicate.OAuthSelfHostedAuthorization {
	return predicate.OAuthSelfHostedAuthorization(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OAuthSelfHostedAuthorization) predicate.OAuthSelfHostedAuthorization {
	return predicate.OAuthSelfHostedAuthorization(sql.NotPredicates(p))
}
